import{_ as p,o as a,c as e,k as t,F as s,D as r,Q as _,t as v,e as f,p as h,m as l,H as u}from"./chunks/framework.68eebb55.js";const T={},o=d=>(h("data-v-c4f42e1c"),d=d(),l(),d),k={class:"lesson"},m=o(()=>t("div",{class:"meta"},[t("span",{class:"tag"},"第 01 / 40 篇"),t("span",null,"第一阶段：AI 与大模型基础"),t("span",null,"阅读约 8 分钟")],-1)),g=o(()=>t("h1",null,"ChatGPT 到底是如何回答问题的？",-1)),b=o(()=>t("p",null,"当你向 ChatGPT 提问「为什么 JavaScript 是单线程的？」时，模型不是简单查询固定答案，而是根据上下文预测下一个 Token。",-1)),I=o(()=>t("h2",null,"一、ChatGPT 的生成流程",-1)),P={class:"visual"},S=o(()=>t("strong",null,"自回归生成（简化）",-1)),A={class:"step"},C={key:0,class:"arrow"},y=_(`<p data-v-c4f42e1c>这个过程叫 Autoregressive Generation。现代聊天产品还可能结合搜索、工具调用和记忆等能力。</p><h2 data-v-c4f42e1c>二、Token 是什么？</h2><p data-v-c4f42e1c>Token 是模型处理文本的基本单位，不一定等于一个汉字或英文单词。</p><pre data-v-c4f42e1c><code data-v-c4f42e1c>输入：我是一名前端开发工程师
示意分词：[&quot;我&quot;,&quot;是一名&quot;,&quot;前端&quot;,&quot;开发&quot;,&quot;工程师&quot;]
示意 ID：[123,456,789,234,567]</code></pre><p data-v-c4f42e1c>以上仅为示意。Token ID 是编号，本身不直接表达语义。</p><h2 data-v-c4f42e1c>三、模型如何生成回答？</h2><p data-v-c4f42e1c>假设输入「JavaScript 是一种」，模型可能计算以下候选 Token 概率：</p><table data-v-c4f42e1c><thead data-v-c4f42e1c><tr data-v-c4f42e1c><th data-v-c4f42e1c>候选</th><th data-v-c4f42e1c>假设概率</th></tr></thead><tbody data-v-c4f42e1c><tr data-v-c4f42e1c><td data-v-c4f42e1c>编程</td><td data-v-c4f42e1c>65%</td></tr><tr data-v-c4f42e1c><td data-v-c4f42e1c>脚本</td><td data-v-c4f42e1c>20%</td></tr><tr data-v-c4f42e1c><td data-v-c4f42e1c>动态</td><td data-v-c4f42e1c>10%</td></tr><tr data-v-c4f42e1c><td data-v-c4f42e1c>其他</td><td data-v-c4f42e1c>5%</td></tr></tbody></table><p data-v-c4f42e1c>选中「编程」后，模型继续预测「语言」等后续 Token。Temperature、Top-p 等参数影响选择策略，模型并非每次都取概率最大的 Token。</p><h2 data-v-c4f42e1c>四、Transformer 与 Attention</h2><p data-v-c4f42e1c>Transformer 是现代大语言模型常用架构。Attention 让模型处理一个位置时可以利用上下文。</p><div class="visual" data-v-c4f42e1c><strong data-v-c4f42e1c>上下文指代示意</strong><p data-v-c4f42e1c>小明把电脑放在桌子上，因为它太重了。</p><div class="cols" data-v-c4f42e1c><div class="panel" data-v-c4f42e1c>电脑：候选指代对象</div><div class="panel" data-v-c4f42e1c>桌子：候选指代对象</div></div><p data-v-c4f42e1c>模型结合上下文学习关联，而不是执行硬编码关键词规则。</p></div><h2 data-v-c4f42e1c>五、为什么模型能回答编程问题？</h2><p data-v-c4f42e1c>模型在训练中学习了大量语言和代码模式，因此可以生成：</p><pre data-v-c4f42e1c><code data-v-c4f42e1c>const sum = (a: number, b: number) =&gt; a + b;</code></pre><p data-v-c4f42e1c><strong data-v-c4f42e1c>生成看起来正确的代码，不代表代码一定正确。</strong>实际工程仍需测试和人工审查。</p><h2 data-v-c4f42e1c>六、React + Node.js 聊天系统</h2>`,17),q={class:"visual"},N={class:"step"},w={key:0,class:"arrow"},D=_('<p data-v-c4f42e1c>聊天应用还需要会话存储、流式输出、权限、限流和安全机制。<strong data-v-c4f42e1c>聊天机器人应用不等于 LLM 本身。</strong></p><h2 data-v-c4f42e1c>七、知识总结</h2><table data-v-c4f42e1c><thead data-v-c4f42e1c><tr data-v-c4f42e1c><th data-v-c4f42e1c>概念</th><th data-v-c4f42e1c>作用</th></tr></thead><tbody data-v-c4f42e1c><tr data-v-c4f42e1c><td data-v-c4f42e1c>LLM</td><td data-v-c4f42e1c>语言生成模型</td></tr><tr data-v-c4f42e1c><td data-v-c4f42e1c>Token</td><td data-v-c4f42e1c>文本处理单位</td></tr><tr data-v-c4f42e1c><td data-v-c4f42e1c>Tokenizer</td><td data-v-c4f42e1c>文本转 Token ID</td></tr><tr data-v-c4f42e1c><td data-v-c4f42e1c>Transformer</td><td data-v-c4f42e1c>序列上下文计算</td></tr><tr data-v-c4f42e1c><td data-v-c4f42e1c>Attention</td><td data-v-c4f42e1c>聚合相关上下文信息</td></tr></tbody></table><h2 data-v-c4f42e1c>学习疑问与解答</h2><p data-v-c4f42e1c>本篇暂无新增问题，后续持续补充。</p><h3 data-v-c4f42e1c>思考题</h3><p data-v-c4f42e1c>为什么 ChatGPT 有时会一本正经地给出错误答案？提示：预测高概率 Token 和验证事实真实性之间有什么区别？</p><footer data-v-c4f42e1c><span data-v-c4f42e1c>第 01 篇</span><a href="./02-token-and-embedding" data-v-c4f42e1c>下一篇 →</a></footer>',8);function G(d,i){return a(),e("article",k,[m,g,b,I,t("div",P,[S,(a(),e(s,null,r(["用户输入","Tokenization：文本切分","Token ID 与向量表示","Transformer 模型计算","计算下一个 Token 的概率","选择下一个 Token","重复生成直到结束"],(c,n)=>(a(),e(s,{key:c},[t("div",A,v(c),1),n<6?(a(),e("div",C,"↓")):f("",!0)],64))),64))]),y,t("div",q,[(a(!0),e(s,null,r(["React UI：用户输入","Node.js API：鉴权与组装 Messages","LLM API：Tokenization 与生成","Node.js：转发流式响应","React UI：实时展示回答"],(c,n)=>(a(),e(s,{key:c},[t("div",N,v(c),1),n<4?(a(),e("div",w,"↓")):f("",!0)],64))),128))]),D])}const L=p(T,[["render",G],["__scopeId","data-v-c4f42e1c"]]),R=JSON.parse('{"title":"01 · ChatGPT 到底是如何回答问题的？","description":"","frontmatter":{"title":"01 · ChatGPT 到底是如何回答问题的？","outline":"deep"},"headers":[],"relativePath":"guide/ai/chatbot-course/01-how-chatgpt-works.md","filePath":"guide/ai/chatbot-course/01-how-chatgpt-works.md","lastUpdated":1792049004000}'),V={name:"guide/ai/chatbot-course/01-how-chatgpt-works.md"},j=Object.assign(V,{setup(d){return(i,c)=>(a(),e("div",null,[u(L)]))}});export{R as __pageData,j as default};
